def TemporalEdge.init (alloc : Unit) (id source target : String) (initial_weight : Float) (initial_quality : EdgeQuality) (timestamp_ns : Timestamp) : TemporalEdge :=
  {
    edge_id := id,
    source := source,
    target := target,
    versions := #[EdgeVersion.init alloc 0 timestamp_ns initial_weight initial_quality],
    current_version := 0,
    valid_from := timestamp_ns,
    valid_to := MAX_TIMESTAMP,
    created_at := timestamp_ns,
    last_modified := timestamp_ns,
