def TemporalGraph.createSnapshot (self : TemporalGraph) : Except String TemporalGraph :=
  self.createSnapshotAtTime self.current_time

def TemporalGraph.createSnapshotAtTime (self : TemporalGraph) (timestamp_ns : Timestamp) : Except String TemporalGraph :=
  let snapshot_id := self.next_snapshot_id
  let mut snapshot := GraphSnapshot.init self.allocator snapshot_id timestamp_ns
  for (node_id, node) in self.nodes.toList do
    match node.getVersionAt timestamp_ns with
    | some v => snapshot := snapshot.recordNodeVersion node_id v.version
    | none => ()
  for (key, edge) in self.edges.toList do
    if edge.isValidAt timestamp_ns then
      match edge.getVersionAt timestamp_ns with
      | some v => snapshot := snapshot.recordEdgeVersion key v.version
      | none => ()
  let history_entry := HistoryEntry.init self.allocator timestamp_ns .create .snapshot "snapshot" none snapshot_id
  .ok {
    self with
    snapshots := self.snapshots.push snapshot,
    history := self.history.push history_entry,
    next_snapshot_id := self.next_snapshot_id + 1
  }

def TemporalGraph.getSnapshot (self : TemporalGraph) (snapshot_id : Nat) : Option GraphSnapshot :=
  self.snapshots.find? (fun s => s.snapshot_id == snapshot_id)

def TemporalGraph.restoreSnapshot (self : TemporalGraph) (snapshot_id : Nat) : Except String TemporalGraph :=
  match self.getSnapshot snapshot_id with
  | some snapshot =>
    let mut new_nodes := self.nodes
    let mut nodes_to_remove : List String := []
    for (node_id, node) in self.nodes.toList do
      match snapshot.getNodeVersion node_id with
      | some target_version =>
        match node.rollback target_version with
        | .ok n => new_nodes := new_nodes.insert node_id n
        | .error e => return .error e
      | none =>
        if node.created_at > snapshot.timestamp then
          nodes_to_remove := node_id :: nodes_to_remove

    for nid in nodes_to_remove do
      new_nodes := new_nodes.erase nid

    let mut new_edges := self.edges
    let mut edges_to_remove : List EdgeKey := []
    for (key, edge) in self.edges.toList do
      match snapshot.getEdgeVersion key with
      | some target_version =>
        match edge.rollback target_version with
        | .ok e => new_edges := new_edges.insert key e
        | .error err => return .error err
      | none =>
        if edge.created_at > snapshot.timestamp then
          edges_to_remove := key :: edges_to_remove

    for ek in edges_to_remove do
      new_edges := new_edges.erase ek

    let history_entry := HistoryEntry.init self.allocator self.current_time .rollback .snapshot "snapshot_restore" none snapshot_id
    .ok { self with nodes := new_nodes, edges := new_edges, history := self.history.push history_entry }
  | none => .error "SnapshotNotFound"

def TemporalGraph.getHistory (self : TemporalGraph) (allocator : Unit) : List HistoryEntry :=
  self.history.toList

def TemporalGraph.getHistoryInRange (self : TemporalGraph) (start_time end_time : Timestamp) (allocator : Unit) : List HistoryEntry :=
  self.history.toList.filter (fun e => e.timestamp ≥ start_time && e.timestamp ≤ end_time)

def TemporalGraph.queryTimeRange (self : TemporalGraph) (start_time end_time : Timestamp) : Except String TemporalQueryResult :=
  let query := TemporalQuery.init self.allocator start_time end_time
  let mut res_nodes : List TemporalNode := []
  for (_, node) in self.nodes.toList do
    if query.nodeMatchesTimeRange node then
      match query.node_filter with
      | some f => if f node then res_nodes := node :: res_nodes
      | none => res_nodes := node :: res_nodes

  let mut res_edges : List TemporalEdge := []
  for (_, edge) in self.edges.toList do
    if query.edgeMatchesTimeRange edge then
      match query.edge_filter with
      | some f => if f edge then res_edges := edge :: res_edges
      | none => res_edges := edge :: res_edges

  .ok { nodes := res_nodes.reverse, edges := res_edges.reverse, query_time := end_time, allocator := self.allocator }

def TemporalGraph.queryWithFilters (self : TemporalGraph) (start_time end_time : Timestamp) (node_filter : Option NodeFilterFn) (edge_filter : Option EdgeFilterFn) : Except String TemporalQueryResult :=
  let query := TemporalQuery.initWithFilters self.allocator start_time end_time node_filter edge_filter
  let mut res_nodes : List TemporalNode := []
  for (_, node) in self.nodes.toList do
    if query.nodeMatchesTimeRange node then
      match query.node_filter with
      | some f => if f node then res_nodes := node :: res_nodes
      | none => res_nodes := node :: res_nodes

  let mut res_edges : List TemporalEdge := []
  for (_, edge) in self.edges.toList do
    if query.edgeMatchesTimeRange edge then
      match query.edge_filter with
      | some f => if f edge then res_edges := edge :: res_edges
      | none => res_edges := edge :: res_edges

  .ok { nodes := res_nodes.reverse, edges := res_edges.reverse, query_time := end_time, allocator := self.allocator }

def TemporalGraph.nodeCount (self : TemporalGraph) : Nat := self.nodes.size

def TemporalGraph.edgeCount (self : TemporalGraph) : Nat := self.edges.size

def TemporalGraph.snapshotCount (self : TemporalGraph) : Nat := self.snapshots.size

def TemporalGraph.historyCount (self : TemporalGraph) : Nat := self.history.size

def TemporalGraph.getValidEdgesAt (self : TemporalGraph) (timestamp_ns : Timestamp) (allocator : Unit) : List TemporalEdge :=
  self.edges.toList.filter (fun p => p.2.isValidAt timestamp_ns) |>.map (fun p => p.2)

def TemporalGraph.getNodeNeighborsAt (self : TemporalGraph) (node_id : String) (timestamp_ns : Timestamp) (allocator : Unit) : List String :=
  let mut neighbors : List String := []
  for (key, edge) in self.edges.toList do
    if edge.isValidAt timestamp_ns then
      if key.source == node_id then neighbors := key.target :: neighbors
      else if key.target == node_id then neighbors := key.source :: neighbors
  neighbors.reverse

def TemporalGraph.computeGraphStateAt (self : TemporalGraph) (timestamp_ns : Timestamp) (allocator : Unit) : Except String (HashMap String QuantumState × HashMap EdgeKey Float) :=
  let mut node_states : HashMap String QuantumState := HashMap.empty
  for (nid, node) in self.nodes.toList do
    match node.getVersionAt timestamp_ns with
    | some v => node_states := node_states.insert nid v.data
    | none => ()

  let mut edge_weights : HashMap EdgeKey Float := HashMap.empty
  for (key, edge) in self.edges.toList do
    if edge.isValidAt timestamp_ns then
      match edge.getVersionAt timestamp_ns with
      | some v => edge_weights := edge_weights.insert key v.weight
      | none => ()

  .ok (node_states, edge_weights)

def TemporalGraph.clone (self : TemporalGraph) (allocator : Unit) : TemporalGraph :=
  let mut new_graph := TemporalGraph.init allocator
  new_graph := { new_graph with current_time := self.current_time, next_snapshot_id := self.next_snapshot_id, next_edge_id := self.next_edge_id }

  let mut new_nodes : HashMap String TemporalNode := HashMap.empty
  for (nid, node) in self.nodes.toList do
    new_nodes := new_nodes.insert nid (node.clone allocator)

  let mut new_edges : HashMap EdgeKey TemporalEdge := HashMap.empty
  for (key, edge) in self.edges.toList do
    new_edges := new_edges.insert key (edge.clone allocator)

  let mut new_snapshots : Array GraphSnapshot := #[]
  for s in self.snapshots do
    new_snapshots := new_snapshots.push (s.clone allocator)

  let mut new_history : Array HistoryEntry := #[]
  for h in self.history do
    new_history := new_history.push (h.clone allocator)

  { new_graph with nodes := new_nodes, edges := new_edges, snapshots := new_snapshots, history := new_history }

